/// Typed Command production.
#[derive(Clone, Debug, PartialEq)]
pub enum Command {
    /// The Workspace form.
    Workspace(WorkspaceTarget),
    /// The WorkspaceNoBack form.
    WorkspaceNoBack(WorkspaceTarget),
    /// The MoveWorkspace form.
    MoveWorkspace(WorkspaceTarget),
    /// The MoveWorkspaceNoBack form.
    MoveWorkspaceNoBack(WorkspaceTarget),
    /// The Rename form.
    Rename(RenameWorkspace),
    /// The Exec form.
    Exec(ShellCommand),
    /// The Exit form.
    Exit,
    /// The Mode form.
    Mode(ModeName),
    /// The Layout form.
    Layout(Layout),
    /// The Split form.
    Split(Axis),
    /// The BorderToggle form.
    BorderToggle,
    /// The Border form.
    Border(Border),
    /// The Persistent form.
    Persistent(Persistence),
    /// The Fullscreen form.
    Fullscreen(Toggle),
    /// The FocusModeToggle form.
    FocusModeToggle,
    /// The FocusParent form.
    FocusParent,
    /// The FocusChild form.
    FocusChild,
    /// The Focus form.
    Focus(Direction),
    /// The Move form.
    Move(Direction),
    /// The Sticky form.
    Sticky(Toggle),
    /// The Floating form.
    Floating(Toggle),
    /// The Resize form.
    Resize(Resize),
    /// The Kill form.
    Kill,
    /// The Reload form.
    Reload,
    /// The Position form.
    Position(Position),
    /// The Weld form.
    Weld(WeldCommand),
    /// The MoveWorkspaceToOutput form.
    MoveWorkspaceToOutput(Vec<Literal>),
}
impl Words for Command {
    fn words(words: &[&str]) -> Result<Self> {
        Ok(match words {
            [
                "move",
                "--no-auto-back-and-forth",
                "container",
                "workspace",
                target @ ..,
            ] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspaceNoBack(target)
            }
            [
                "move",
                "--no-auto-back-and-forth",
                "window",
                "workspace",
                target @ ..,
            ] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspaceNoBack(target)
            }
            ["move", "workspace", "to", "output", outputs @ ..] => {
                let outputs = Literals::words(outputs)?;
                Self::MoveWorkspaceToOutput(outputs.0)
            }
            ["workspace", "--no-auto-back-and-forth", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::WorkspaceNoBack(target)
            }
            ["workspace", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::Workspace(target)
            }
            ["rename", "workspace", rename @ ..] => {
                let rename = RenameWorkspace::words(rename)?;
                Self::Rename(rename)
            }
            ["move", "--no-auto-back-and-forth", "workspace", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspaceNoBack(target)
            }
            ["move", "workspace", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspace(target)
            }
            [
                "move",
                "--no-auto-back-and-forth",
                "to",
                "workspace",
                target @ ..,
            ] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspaceNoBack(target)
            }
            ["move", "to", "workspace", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspace(target)
            }
            [
                "move",
                "--no-auto-back-and-forth",
                "container",
                "to",
                "workspace",
                target @ ..,
            ] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspaceNoBack(target)
            }
            ["move", "container", "to", "workspace", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspace(target)
            }
            [
                "move",
                "--no-auto-back-and-forth",
                "window",
                "to",
                "workspace",
                target @ ..,
            ] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspaceNoBack(target)
            }
            ["move", "window", "to", "workspace", target @ ..] => {
                let target = WorkspaceTarget::words(target)?;
                Self::MoveWorkspace(target)
            }
            ["exec", command @ ..] => {
                let command = ShellCommand::words(command)?;
                Self::Exec(command)
            }
            ["exec_always", command @ ..] => {
                let command = ShellCommand::words(command)?;
                Self::Exec(command)
            }
            ["mode", name] => {
                let name = ModeName::word(name)?;
                Self::Mode(name)
            }
            ["layout", layout @ ..] => {
                let layout = Layout::words(layout)?;
                Self::Layout(layout)
            }
            ["splith"] => Self::Split(Axis::Horizontal),
            ["splitv"] => Self::Split(Axis::Vertical),
            ["split", axis] => {
                let axis = Axis::word(axis)?;
                Self::Split(axis)
            }
            ["border", "toggle"] => Self::BorderToggle,
            ["border", border @ ..] => {
                let border = Border::words(border)?;
                Self::Border(border)
            }
            ["weld", "persistent", persistence @ ..] => {
                let persistence = Persistence::words(persistence)?;
                Self::Persistent(persistence)
            }
            ["fullscreen"] => Self::Fullscreen(Toggle::Toggle),
            ["fullscreen", toggle] => {
                let toggle = Toggle::word(toggle)?;
                Self::Fullscreen(toggle)
            }
            ["focus", "mode_toggle"] => Self::FocusModeToggle,
            ["focus", "parent"] => Self::FocusParent,
            ["focus", "child"] => Self::FocusChild,
            ["focus", direction] => {
                let direction = Direction::word(direction)?;
                Self::Focus(direction)
            }
            ["move", direction] => {
                let direction = Direction::word(direction)?;
                Self::Move(direction)
            }
            ["sticky", toggle] => {
                let toggle = Toggle::word(toggle)?;
                Self::Sticky(toggle)
            }
            ["floating", toggle] => {
                let toggle = Toggle::word(toggle)?;
                Self::Floating(toggle)
            }
            ["resize", resize @ ..] => {
                let resize = Resize::words(resize)?;
                Self::Resize(resize)
            }
            ["move", "absolute", "position", x, y] => {
                let x = FiniteFloat::word(x)?;
                let y = FiniteFloat::word(y)?;
                Self::Position(Position { x: x.0, y: y.0 })
            }
            ["weld", command @ ..] => {
                let command = WeldCommand::words(command)?;
                Self::Weld(command)
            }
            ["exit"] => Self::Exit,
            ["kill"] => Self::Kill,
            ["reload"] => Self::Reload,
            _ => {
                return Err(unsupported(format!(
                    "unsupported Command: {}",
                    words.join(" ")
                )));
            }
        })
    }
}
